---@param data LoginFailedData
function UnifySDK_Account:OnLoginFailed(data)
    self.isLogin = false
    logError( " OnLoginFailed ")
end

---@param data LogoutSuccessData
function UnifySDK_Account:OnLogoutSuccess(data)
    log("---   OnLogoutSuccess... ")
    if PlayerPrefs.GetInt("4WDClienType",-1)==1 then
        return
    end
    self.isLogin = false
    LoginFuncHelper:LoginOut_GameBackToLogin_Combine(false, true, nil, true)
end

---@param data ExitSuccessData
function UnifySDK_Account:OnExitSuccess(data)
    log("---   OnExitSuccess... ")
    CS.UnityEngine.Application.Quit()
end

---@param data PrivacyAgreeData
function UnifySDK_Account:OnPrivacyAgree(data) ----该方法现在放到了C#中  lua初始化过晚
    if UnifySDKManager:Get():IUnifySDKByType(UnifySDKType.QuickSDK) then
        UnifySDKManager:Get():IUnifySDKByType(UnifySDKType.QuickSDK):OnInit()
    end
    CS.UniLang.ApplyPermissions:Get():ApplyPermission()
end

---@param data PrivacyRefuseData
function UnifySDK_Account:OnPrivacyRefuse(data) ----该方法现在放到了C#中  lua初始化过晚
    local boxfunc = function()
        local str = CommonHelper:GetTempStr_Default(TemplateStringID.MakeSureToQuitTheGame)
        local ret = MessageBoxHelp:Get():OpenBox_OKCancel(UIColor.Blue, str)
        if ret == MessageBoxHelp.BtnType.OK then
            CS.UnityEngine.Application.Quit()
        end
        if ret == MessageBoxHelp.BtnType.Cancel then
            UnifySDKManager:Get():IAccount():ShowPrivacy()
        end
    end
    MessageBoxHelp.Get():StartCoroutineBox(boxfunc)
end


